class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def check(node, lo, hi):
            if not node:
                return True
            if not (lo < node.val < hi):
                return False
            return check(node.left, lo, node.val) and check(node.right, node.val, hi)
        return check(root, float("-inf"), float("inf"))

class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        prev = float("-inf")
        def inorder(node):
            nonlocal prev
            if not node:
                return True
            if not inorder(node.left):
                return False
            if node.val <= prev:        # 必须比前一个大
                return False
            prev = node.val
            return inorder(node.right)
        return inorder(root)

class Solution:
    def isValidBST(self, root: Optional[TreeNode], lo=float("-inf"), hi=float("inf")) -> bool:
        if not root:
            return True
        return (lo < root.val < hi
                and self.isValidBST(root.left, lo, root.val)
                and self.isValidBST(root.right, root.val, hi))

